CREATE DATABASE IF NOT EXISTS studyswap; USE studyswap;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('STUDENT','ADMIN','DELIVERY_PARTNER') NOT NULL DEFAULT 'STUDENT', credits INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE books (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, listing_type ENUM('SELL','RENT','EXCHANGE','DONATE') NOT NULL, selling_price DECIMAL(10,2) NULL, rental_price DECIMAL(10,2) NULL, security_deposit DECIMAL(10,2) NULL, status ENUM('AVAILABLE','RESERVED','RENTED','SOLD','EXCHANGED','DONATED','UNAVAILABLE') DEFAULT 'AVAILABLE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), CONSTRAINT valid_listing_amounts CHECK ((listing_type='SELL' AND selling_price>0 AND rental_price IS NULL AND security_deposit IS NULL) OR (listing_type='RENT' AND rental_price>0) OR (listing_type IN ('EXCHANGE','DONATE') AND selling_price IS NULL AND rental_price IS NULL AND security_deposit IS NULL)));
CREATE TABLE wishlist (user_id BIGINT NOT NULL, book_id BIGINT NOT NULL, PRIMARY KEY(user_id,book_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(book_id) REFERENCES books(id));
